-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Unit Weight from cells/IMPORT Unit Weight.csv in the folder of input cells. Two rows for one cell add up.
INSERT OR REPLACE INTO "IMPORT Unit Weight" SELECT coalesce(k0."SKU", error('cells name a member SKU does not have: ' || c."SKU")), sum(c.value::DOUBLE)
FROM read_csv('cells/IMPORT Unit Weight.csv', header = true, all_varchar = true) c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU"
GROUP BY ALL;
